//! Constants transcribed mechanically from the original Java implementation
//! (`FinalCode/src/finalcode/Main.java`, 2011). Do not edit by hand.

// Some dimer values coincidentally resemble mathematical constants (e.g. 0.4343).
#![allow(clippy::approx_constant)]

/// One amino-acid property scale and its weight in the integrated score.
pub struct PropertyScale {
    pub name: &'static str,
    pub description: &'static str,
    /// Values in [`crate::amino::ALPHABET`] order.
    pub values: [f64; 20],
    pub coefficient: f64,
}

