/// Weight of the position-specific frequency (PSSM) term.
pub const PSSM_COEFFICIENT: f64 = 17.66;

/// Weight of the dipeptide (dimer) term.
pub const DIMER_COEFFICIENT: f64 = 5.553;

/// Decision threshold used by the original program. It was not calibrated for
/// 21-residue windows: virtually every lysine scores above it.
pub const LEGACY_THRESHOLD: f64 = 212.368;

